import { cva, type VariantProps } from "class-variance-authority";
import type { ComponentProps } from "react";
import { cn } from "@/lib/utils";
import { Piano as PianoPrimitive } from "@/components/audio-ui/piano/react";

/**
 * How each part of the keyboard is drawn, by its `data-slot`. A part's look
 * follows its attributes, never the keyboard's props: the React piano applies
 * these classes, and `registry:build` writes them as plain CSS on the parts
 * for every other framework. The root carries `data-size`; a key, its
 * `data-color` and `data-selected`.
 */
export const pianoParts = Object.freeze({
  piano:
    "rounded-xl border border-transparent bg-card shadow-xs ring-1 ring-foreground/10 transition-[color,border-color,box-shadow,opacity] duration-150 ease-out hover:ring-4 hover:ring-ring/50 has-[:focus-visible]:ring-4 has-[:focus-visible]:ring-ring/50 active:ring-4 active:ring-ring/50 has-[:focus-visible]:border-ring active:border-ring motion-reduce:transition-none [--piano-key-white:oklch(0.985_0_0)] [--piano-key-black:oklch(0.205_0_0)] w-full touch-none select-none overflow-hidden data-disabled:pointer-events-none data-disabled:opacity-50",
  "piano-key": "top-0 outline-none transition-colors duration-100 ease-out focus-visible:z-20 focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:ring-inset data-[color=white]:z-0 data-[color=white]:h-full data-[color=white]:border-[color:color-mix(in_oklab,var(--piano-key-black)_30%,transparent)] data-[color=white]:border-x data-[color=white]:bg-(--piano-key-white) data-[color=black]:z-10 data-[color=black]:h-[60%] data-[color=black]:rounded-b-[min(var(--radius-sm),4px)] data-[color=black]:bg-(--piano-key-black) data-[selected]:data-[color]:bg-primary motion-reduce:transition-none cursor-pointer",
});

/** The parts whose look changes with the keyboard's `data-size`, by size. */
export const pianoSizes = Object.freeze({
  piano: Object.freeze({
    default: "h-32",
    lg: "h-40",
    sm: "h-24",
  }),
});

const pianoVariants = cva(pianoParts.piano, {
  defaultVariants: { size: "default" },
  variants: { size: pianoSizes.piano },
});

interface PianoProps
  extends Omit<
      ComponentProps<typeof PianoPrimitive.Root>,
      "children" | "className"
    >,
    VariantProps<typeof pianoVariants> {
  className?: string;
}

export function Piano({ className, size, ...props }: PianoProps) {
  return (
    <PianoPrimitive.Root
      className={cn(pianoVariants({ size }), className)}
      data-size={size ?? "default"}
      data-slot="piano"
      {...props}
    >
      {({ pitches }) =>
        pitches.map((pitch) => (
          <PianoPrimitive.Key
            className={pianoParts["piano-key"]}
            key={pitch}
            pitch={pitch}
          />
        ))
      }
    </PianoPrimitive.Root>
  );
}
